     assert.equal(portal.rateTicket(store, globex, 9999, 4), null);
     assert.equal(store.getTicket(t.id).rating_score, null);
   });

   test('the store write itself refuses a wrong organisation, a non-resolved ticket and a rated ticket', () => {
     const store = createStore();
     const t = resolved(store);
     assert.equal(store.rateTicket(t.id, { orgId: 2, score: 4, at: 'x' }), null);
     store.updateTicket(t.id, { status: 'open' });
     assert.equal(store.rateTicket(t.id, { orgId: 1, score: 4, at: 'x' }), null);
     store.updateTicket(t.id, { status: 'resolved' });
     assert.equal(store.rateTicket(t.id, { orgId: 1, score: 4, at: 'x' }).rating_score, 4);
