   // The customer rates a resolved ticket once. Organisation first, so a stranger learns nothing; then the score; then the status.
   function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
     const t = store.getTicket(id);
     if (!t || t.org_id !== customer.orgId) return null;
     if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
     if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
     if (t.rating_score != null) throw new Error('this ticket is already rated');
     const rated = store.rateTicket(id, { orgId: customer.orgId, score, at: now.toISOString() });
     if (!rated) throw new Error('this ticket is already rated or has changed; please reload');
     return getMyTicket(store, customer, id);
   }
   ```
