   ```js
   'use strict';
   // Nightly. For each agent who owns tickets rated in the past seven days: how many ratings, and their average.
   // The window is rolling (run time minus seven days, inclusive). Agents without ratings get no row.
   const WINDOW_DAYS = 7;
   const DAY = 24 * 60 * 60 * 1000;

   function weeklyCsat(store, { now = new Date() } = {}) {
     const since = now.getTime() - WINDOW_DAYS * DAY;
     const scores = new Map();
     for (const t of store.listTickets()) {
       if (t.rating_score == null || t.owner_id == null) continue;
       if (new Date(t.rated_at).getTime() < since) continue;
       if (!scores.has(t.owner_id)) scores.set(t.owner_id, []);
       scores.get(t.owner_id).push(t.rating_score);
     }
     const weekEnding = now.toISOString().slice(0, 10);
     const rows = [...scores].map(([owner_id, list]) => ({
       owner_id,
       week_ending: weekEnding,
       ratings: list.length,
       average: Number((list.reduce((a, b) => a + b, 0) / list.length).toFixed(2)),
     }));
     for (const row of rows) store.saveCsatSummary(row);
     return rows;
   }

   module.exports = { weeklyCsat, WINDOW_DAYS };
   ```
   Evidence: `node --test test/weekly-csat.test.js` green.
